input.command:
node -c index.html 2>&1; echo "check js syntax"; node -e "
const fs=require('fs');
let html=fs.readFileSync('index.html','utf8');
let m=html.match(/<script>([\s\S]*?)<\/script>/g);
let js=m.map(s=>s.replace(/<\/?script>/g,'')).join('\n');
fs.writeFileSync('/tmp/test.js', js);
require('child_process').execSync('node --check /tmp/test.js', {stdio:'inherit'});
console.log('JS OK, elements:', (js.match(/id:'/g)||[]).length);
"

